raw.css:
:root {
  --color-primary: #8B4513;
  --color-primary-dark: #5c2e0f;
  --color-accent: #d4a574;
  --color-accent-on-dark: #f5deb3;
  --color-light: #faf9f7;
  --color-dark: #2c2c2c;
  --color-text: #333333;
  --color-border: #e0d5c8;
  --color-success: #2d5016;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: "Trebuchet MS", Verdana, sans-serif;
  --radius: 8px;
  --shadow: 0 2px 8px rgba(92, 46, 15, 0.15);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  line-height: 1.6;
  background-color: var(--color-light);
}

heading {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
}

h1 {
  font-size: 2.5rem;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
}

h2 {
  font-size: 2rem;
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
}

h3 {
  font-size: 1.3rem;
  margin-bottom: var(--spacing-sm);
}

p {
  margin-bottom: var(--spacing-sm);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  font-weight: 600;
}

a:hover {
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

.site-header {
  background-color: white;
  border-bottom: 2px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  display: inline-block;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 4px;
}

.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xl) 0;
  margin-top: var(--spacing-xl);
  border-top: 2px solid var(--color-accent);
}

.site-footer p {
  margin-bottom: var(--spacing-xs);
  font-size: 0.95rem;
}

.site-footer a {
  color: var(--color-accent-on-dark);
  font-weight: 600;
}

.site-footer a:hover {
  text-decoration: underline;
}

.site-footer strong {
  color: var(--color-accent-on-dark);
  display: block;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-xs);
}

button, .btn {
  display: inline-block;
  background-color: var(--color-primary-dark);
  color: white;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  min-height: 44px;
  line-height: 1.2;
  text-decoration: none;
  text-align: center;
  transition: background-color 0.2s ease;
}

button:hover, .btn:hover {
  background-color: var(--color-primary);
}

button:focus, .btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active {
  transform: translateY(2px);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

input, textarea, select {
  width: 100%;
  padding: 0.75rem;
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 2px solid var(--color-border);
  border-radius: var(--radius);
  background-color: white;
  color: var(--color-text);
  min-height: 44px;
  line-height: 1.4;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(92, 46, 15, 0.1);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.grid {
  display: grid;
  gap: var(--spacing-md);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.card {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--color-border);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 12px rgba(92, 46, 15, 0.2);
}

.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: white;
  padding: var(--spacing-xl) var(--spacing-lg);
  text-align: center;
}

.hero h1 {
  color: white;
  font-size: clamp(2rem, 8vw, 3.5rem);
}

.hero p {
  font-size: 1.2rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-md);
}

section {
  padding: var(--spacing-xl) var(--spacing-lg);
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.price-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid var(--color-border);
}

.price-row:last-child {
  border-bottom: none;
}

.service-name {
  font-weight: 600;
  color: var(--color-text);
}

.service-price {
  font-weight: 700;
  color: var(--color-primary-dark);
  font-size: 1.1rem;
}

@media (max-width: 600px) {
  :root {
    font-size: 15px;
  }

  h1 {
    font-size: 1.8rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  .logo {
    font-size: 1.2rem;
  }

  section {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .grid {
    grid-template-columns: 1fr;
  }

  .price-row {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-sm);
  }

  button, .btn {
    width: 100%;
  }

  input, textarea, select {
    font-size: 16px;
  }
}

@media (min-width: 601px) {
  .site-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  section {
    padding: var(--spacing-xl) var(--spacing-lg);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

